let state=null;
let activePage='events';
let selectedMatch=null;
let playerQuery='';
let eventQuery='';
let messageTab='mass';
let selectedGame='王者万象棋';
let eventUid='';
let eventStatus='全部';
let eventMonth='全部';
let groupSession='全部';
let advanceQuery='';
let advanceStatus='全部';
let receiptUnreadOnly=false;
let pendingMessage=null;
const app=document.getElementById('b-app');
const modal=document.getElementById('b-modal');
const modalBody=document.getElementById('b-modal-body');
const titles={events:'万象棋赛事',rules:'规则配置',players:'配置选手',leaders:'领队库',groups:'分组管理',review:'赛果审核',advance:'晋级管理',messages:'消息中心'};

function esc(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(text){const el=document.getElementById('b-toast');el.textContent=text;el.hidden=false;clearTimeout(el.timer);el.timer=setTimeout(()=>el.hidden=true,2500)}
async function request(url,options={}){const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw new Error(data.error||'操作失败');return data}
function post(url,data={}){return request(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})}
async function refresh(){state=await request('/api/state');render()}
function openModal(html){modalBody.innerHTML=html;modal.hidden=false}
function closeModal(){modal.hidden=true}
function statusTag(status){return status==='confirmed'?'<span class="c-tag confirmed">已审核</span>':status==='pending'?'<span class="c-tag pending">待审核</span>':'<span class="c-tag">等待上传</span>'}
async function goPage(page){activePage=page;closeModal();state=await request('/api/state');render()}
function gameEvents(){return state.event_options.filter(e=>e.game===selectedGame)}
function leaderText(user){return user.leader_uid?`${user.leader}（UID ${user.leader_uid}）`:'待分配'}
function context(stage=true){return `<section class="b-panel b-context"><span>当前赛事</span><select class="b-select" data-action="context-event">${gameEvents().map(e=>`<option value="${e.id}" ${e.id===state.current_event_id?'selected':''}>${esc(e.name)}（ID ${e.id}）</option>`).join('')}</select>${stage?`<span>当前赛段</span><select class="b-select" data-action="context-stage">${state.stage_options.map(s=>`<option value="${s.id}" ${s.id===state.current_stage_id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}<span class="c-muted">B 端当前操作对象，同时对应 C 端演示赛事</span></section>`}
function downloadCsv(filename,rows){const csv='\ufeff'+rows.map(row=>row.map(cell=>`"${String(cell).replace(/"/g,'""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download=filename;link.click();URL.revokeObjectURL(link.href)}

function render(){
  document.getElementById('b-page-title').textContent=titles[activePage];
  document.getElementById('b-demo-date').value=state.event.demo_date;
  document.querySelector('.b-breadcrumb').textContent=`首页 / 赛事管理 / ${selectedGame} / `;
  document.querySelectorAll('.b-board').forEach(btn=>btn.classList.toggle('on',btn.dataset.game===selectedGame));
  document.querySelectorAll('[data-page]').forEach(btn=>btn.classList.toggle('on',btn.dataset.page===activePage));
  if(activePage==='events')renderEvents();
  if(activePage==='rules')renderRules();
  if(activePage==='players')renderPlayers();
  if(activePage==='leaders')renderLeaders();
  if(activePage==='groups')renderGroups();
  if(activePage==='review')renderReview();
  if(activePage==='advance')renderAdvance();
  if(activePage==='messages')renderMessages();
}

function renderEvents(){
  const events=gameEvents().filter(e=>(!eventQuery||e.name.includes(eventQuery)||String(e.id).includes(eventQuery))&&(!eventUid||e.user_uids.includes(eventUid))&&(eventStatus==='全部'||e.status===eventStatus)&&(eventMonth==='全部'||e.date_range.includes(eventMonth)));
  app.innerHTML=`<section class="b-panel" style="padding:10px 14px"><span class="c-muted">扶摇 · 赛事管理（当前板块：${selectedGame}，可在左侧切换其他游戏板块）</span></section>
    <section class="b-panel"><div class="b-filters"><input class="b-input" id="b-event-uid" value="${esc(eventUid)}" placeholder="UID　请输入 UID"><select class="b-select" id="b-event-status"><option ${eventStatus==='全部'?'selected':''}>全部</option><option ${eventStatus==='进行中'?'selected':''}>进行中</option><option ${eventStatus==='未开始'?'selected':''}>未开始</option><option ${eventStatus==='已结束'?'selected':''}>已结束</option></select><input class="b-input" id="b-event-keyword" value="${esc(eventQuery)}" placeholder="联想词　输入赛事名称或 ID"><select class="b-select" id="b-event-month"><option value="全部">时间　全部</option><option value="2025-12" ${eventMonth==='2025-12'?'selected':''}>2025 年 12 月</option><option value="2025-09" ${eventMonth==='2025-09'?'selected':''}>2025 年 9 月</option></select><button class="b-button" data-action="event-search">搜索</button><button class="b-button o" data-action="event-clear">重置</button><button class="b-button" data-action="create-event" style="margin-left:auto">＋ 新增</button></div>
      <table class="b-table"><thead><tr><th>赛事 ID</th><th>赛事名称</th><th>赛季</th><th>报名费</th><th>赛事状态</th><th>banner 时间</th><th>赛事时间</th><th>报名时间</th><th>赛段</th><th>操作</th></tr></thead><tbody>${events.length?events.map(e=>`<tr class="${e.id===state.current_event_id?'b-current-row':''}"><td>${e.id}</td><td><b>${esc(e.name)}</b></td><td>${esc(e.season)}</td><td>${e.fee}</td><td><span class="c-tag ${e.status==='进行中'?'confirmed':''}">${e.status}</span></td><td>${e.banner_time}</td><td>${e.date_range}</td><td>${e.signup_time}</td><td>${e.stage_count} 个</td><td><button data-action="event-page" data-id="${e.id}" data-target="rules">规则配置</button><button data-action="event-page" data-id="${e.id}" data-target="players">配置选手</button><button data-action="event-page" data-id="${e.id}" data-target="advance">晋级管理</button><button data-action="event-page" data-id="${e.id}" data-target="groups">分组</button><button data-action="event-page" data-id="${e.id}" data-target="review">赛果</button></td></tr>`).join(''):'<tr><td colspan="10" class="b-empty">没有符合筛选条件的赛事，请调整条件后重试</td></tr>'}</tbody></table>
      <p class="b-note">每一行是一个独立大赛事；进入规则配置后，再管理该赛事下的海选、淘汰、决赛等赛段。</p>
    </section>`;
}

function stageTabs(){return `<div class="b-stage-tabs">${state.stage_options.map(s=>`<button class="${s.id===state.current_stage_id?'on':''}" data-action="select-stage" data-id="${s.id}">${esc(s.name)}</button>`).join('')}<button class="add" data-action="create-stage">＋ 新增赛段</button><button class="delete" data-action="delete-stage">删除当前赛段</button><button class="back" data-page="events">返回赛事列表</button></div>`}
function customFieldsHtml(fields,scope){return `${fields.length?fields.map(field=>`<div class="b-log"><span style="flex:1"><b>${esc(field.label)}</b> <span class="c-tag">${field.type==='select'?'自定义选项':'文本输入'}</span><br><span class="c-muted">${field.required?'必填':'选填'}${field.options.length?` · 选项：${field.options.join(' / ')}`:''}</span></span><button class="b-button o" type="button" data-action="delete-field" data-scope="${scope}" data-id="${field.id}">删除</button></div>`).join(''):'<p class="c-muted">暂无自定义收集项，可点击下方按钮添加。</p>'}<button class="b-button o" type="button" data-action="add-field" data-scope="${scope}">＋ 添加自定义收集项</button>`}

function renderRules(){
  const e=state.event;
  const isFirstStage=state.stage_options[0].id===state.current_stage_id;
  const fields=[['contact','联系方式（微信 / QQ 二选一）'],['phone','手机号'],['game_nick','游戏昵称'],['game_id','游戏 ID / 编号'],['channel','游戏账号渠道'],['wechat_qr','微信二维码（可选）'],['game_shot','游戏主页截图（可选）']];
  app.innerHTML=`${context(false)}<section class="b-panel">${stageTabs()}<form id="b-rules-form"><div class="b-panel-title"><h2>${esc(e.name)} · ${esc(e.stage)}规则 <small>赛段名称、时间与规则独立配置</small></h2><button class="b-button" type="submit">保存当前赛段规则</button></div>
    <div class="b-form-grid"><div class="b-form-item"><label>赛段名称</label><input class="b-input" name="name" value="${esc(e.stage)}" required></div><div class="b-form-item"><label>每日可选场次（整点）</label><div id="b-session-inputs">${e.sessions.map((session,index)=>`<div class="b-session-input" style="display:flex;gap:6px;margin-bottom:5px"><input class="b-input" type="time" step="3600" name="session" value="${session}" required><button class="b-button o" type="button" data-action="remove-session" title="删除该场次">删除</button></div>`).join('')}</div><button class="b-button o" type="button" data-action="add-session">＋ 添加场次</button></div><div class="b-form-item"><label>赛段开始日期</label><input class="b-input" type="date" name="start_date" value="${e.start_date}" required></div><div class="b-form-item"><label>赛段结束日期</label><input class="b-input" type="date" name="end_date" value="${e.end_date}" required></div><div class="b-form-item"><label>每日默认局数</label><input class="b-input" type="number" min="1" max="6" name="daily_matches" value="${e.default_matches}"></div><div class="b-form-item"><label>最低有效参赛天数（最多 ${e.days.length} 天）</label><input class="b-input" type="number" min="1" max="${e.days.length}" name="min_valid_days" value="${e.min_valid_days}"></div><div class="b-form-item"><label>取最好 X 天累计（最多 ${e.days.length} 天）</label><input class="b-input" type="number" min="1" max="${e.days.length}" name="best_days" value="${e.best_days}"></div><div class="b-form-item"><label>最低晋级积分</label><input class="b-input" type="number" min="0" name="min_score" value="${e.min_score}"></div><div class="b-form-item"><label>晋级名额</label><input class="b-input" type="number" min="1" name="advance_quota" value="${e.advance_quota}"></div><div class="b-form-item"><label>每组人数</label><input class="b-input" type="number" min="2" max="6" name="group_size" value="${e.group_size}"></div></div>
    <div class="b-rule-summary"><b>当前赛段规则摘要：</b>${e.start_date} 至 ${e.end_date}，每日 ${e.sessions.join(' / ')} 场；完成当天全部 ${e.default_matches} 局并审核后形成有效参赛日。至少 ${e.min_valid_days} 个有效日，取最好 ${e.best_days} 天累计，达到 ${e.min_score} 分后按排名取前 ${e.advance_quota} 人。</div>
    <section class="b-inner-section"><h3>名次积分配置 <small>单局预记，当日完成全部局次后统一结算</small></h3><div class="b-form-grid" style="grid-template-columns:repeat(6,1fr)">${e.points.map((point,index)=>`<div class="b-form-item"><label>第 ${index+1} 名</label><input class="b-input" type="number" name="point${index}" value="${point}"></div>`).join('')}</div></section>
    <section class="b-inner-section"><h3>赛事首次报名资料 <small>赛事级配置，保存后决定报名表单</small></h3><div class="b-checks">${fields.map(([key,label])=>`<label><input type="checkbox" name="fields" value="${key}" ${e.registration_fields.includes(key)?'checked':''}>${label}</label>`).join('')}</div><div style="margin-top:14px"><h4>自定义收集项</h4>${customFieldsHtml(e.custom_fields,'event')}</div></section>
    <section class="b-inner-section"><h3>当前赛段报名设置 <small>可独立决定是否需要重新报名及收集字段</small></h3><div class="b-checks"><label><input type="checkbox" name="require_signup" ${isFirstStage?'checked disabled':e.require_signup?'checked':''}>进入本赛段前需要重新报名${isFirstStage?'（首个赛段强制）':''}</label></div><p class="b-note">${isFirstStage?'首个赛段必须报名，不能取消。':'后续赛段可取消重新报名并直接沿用赛事首次报名；勾选后，未选择字段则沿用赛事字段，也可添加本赛段专属收集项。'}</p><div class="b-checks">${fields.map(([key,label])=>`<label><input type="checkbox" name="stage_fields" value="${key}" ${e.stage_registration_fields.includes(key)?'checked':''}>${label}</label>`).join('')}</div><div style="margin-top:14px"><h4>赛段专属自定义收集项</h4>${customFieldsHtml(e.stage_custom_fields,'stage')}</div></section>
  </form></section>
  <section class="b-panel"><div class="b-panel-title"><h2>单日局数调整 <small>赛段默认值 + 单日调整，未单独设置日期沿用默认值</small></h2></div><table class="b-table"><thead><tr><th>日期</th><th>可选场次</th><th>要求完成局数</th><th>配置来源</th><th>操作</th></tr></thead><tbody>${e.days.map(day=>`<tr><td>${day}</td><td>${e.sessions.join(' / ')}</td><td>${e.daily_overrides[day]||e.default_matches} 局</td><td>${e.daily_overrides[day]?'<span class="c-tag pending">单日调整</span>':'赛段默认'}</td><td><button data-action="day-override" data-date="${day}">编辑</button></td></tr>`).join('')}</tbody></table></section>
  <section class="b-panel"><div class="b-panel-title"><h2>规则变更记录 <small>正式名单不会被规则修改静默改变</small></h2></div>${state.logs.slice(0,8).map(log=>`<div class="b-log"><time>${esc(log.time)}</time><span>${esc(log.operator)} · ${esc(log.text)}</span></div>`).join('')}</section>`;
}

function renderPlayers(){
  const e=state.event;
  const users=state.users.filter(u=>!playerQuery||u.nickname.includes(playerQuery)||u.uid.includes(playerQuery)||u.game_nick.includes(playerQuery));
  app.innerHTML=`${context()}<section class="b-panel"><div class="b-panel-title"><h2>设置比赛用户 · ${esc(e.name)} <small>${esc(e.stage)}</small></h2></div>
    <div class="b-filters"><form id="b-player-search" class="b-actions"><input class="b-input" name="query" value="${esc(playerQuery)}" placeholder="UID / 昵称 / 游戏昵称"><button class="b-button" type="submit">查询</button></form><button class="b-button o" data-action="refresh">同步</button><button class="b-button" data-action="add-player">新增 / 手工补录</button><button class="b-button o" data-action="player-template">获取比赛玩家模板</button><button class="b-button" data-action="assign-leaders">一键匹配领队</button></div>
    <div class="b-rule-summary">当前规则：至少 ${e.min_valid_days} 个有效日 / 取最好 ${e.best_days} 天 / ${e.min_score} 分达标 / 前 ${e.advance_quota} 名 <button class="c-text-btn" data-page="rules">查看规则</button><button class="c-text-btn" data-page="advance" style="margin-left:16px">进入晋级管理 →</button></div>
    <table class="b-table" style="margin-top:14px"><thead><tr><th>用户 ID</th><th>昵称</th><th>资料</th><th>领队归属</th><th>次日确认</th><th>今日完赛</th><th>有效天数</th><th>计入成绩</th><th>总积分</th><th>晋级状态</th><th>操作</th></tr></thead><tbody>${users.map(u=>{const s=state.stats[u.uid];return `<tr><td>${u.uid}</td><td>${esc(u.nickname)}<br><span class="c-muted">${esc(u.game_nick)}</span></td><td><button data-action="player-detail" data-uid="${u.uid}">查看资料</button></td><td><button class="c-tag ${u.leader_uid?'confirmed':'pending'}" data-action="assign-player-leader" data-uid="${u.uid}" title="点击调整领队">${esc(leaderText(u))}</button></td><td>${e.next_date} ${esc(u.next_session)} ✓</td><td>${s.played}/${e.daily_matches}<br><span class="c-muted">审核 ${s.confirmed} 局</span></td><td>${s.valid_days}/${e.min_valid_days}</td><td>最好 ${e.best_days} 天</td><td>${s.total_score}</td><td>${u.advance_official?'<span class="c-tag advance">已晋级</span>':s.expected_advance?'<span class="c-tag pending">预计晋级·待发布</span>':'<span class="c-tag">进行中</span>'}</td><td><button data-action="score-detail" data-uid="${u.uid}">成绩明细</button></td></tr>`}).join('')}</tbody></table>
    <p class="b-note">今日未打满要求局数时，当天积分为 0 且不计有效天数；预计晋级不等于正式晋级。</p></section>`;
}

function renderLeaders(){
  const leaders=state.leader_options;
  app.innerHTML=`${context(false)}<div class="b-stats"><div class="b-stat"><b>${leaders.length}</b><span>领队总数</span></div><div class="b-stat"><b>${leaders.filter(l=>l.enabled).length}</b><span>启用中</span></div><div class="b-stat"><b>${leaders.reduce((sum,l)=>sum+l.assigned_count,0)}</b><span>已分配选手</span></div><div class="b-stat"><b>${leaders.reduce((sum,l)=>sum+l.capacity,0)}</b><span>总容量</span></div><div class="b-stat"><b>${leaders.filter(l=>l.assigned_count>=l.capacity).length}</b><span>已满员领队</span></div><div class="b-stat"><b>${leaders.filter(l=>!l.enabled).length}</b><span>已停用</span></div></div>
    <section class="b-panel"><div class="b-panel-title"><h2>领队库 <small>平台级 UID 数据，自动分配与手动调整共用</small></h2><button class="b-button" data-action="add-leader">＋ 新增领队</button></div><div class="b-rule-summary">自动分配仅使用“启用中且未满员”的领队；领队 UID 会同步显示在选手资料、成绩明细和 C 端。</div><table class="b-table" style="margin-top:14px"><thead><tr><th>领队 UID</th><th>昵称</th><th>已分配 / 容量</th><th>剩余名额</th><th>状态</th><th>操作</th></tr></thead><tbody>${leaders.map(l=>`<tr><td><b>${l.uid}</b></td><td>${esc(l.name)}</td><td>${l.assigned_count} / ${l.capacity}</td><td>${Math.max(0,l.capacity-l.assigned_count)}</td><td>${l.enabled?'<span class="c-tag confirmed">启用中</span>':'<span class="c-tag invalid">已停用</span>'}</td><td><button data-action="edit-leader" data-uid="${l.uid}">编辑容量</button><button data-action="toggle-leader" data-uid="${l.uid}">${l.enabled?'停用':'启用'}</button><button data-action="delete-leader" data-uid="${l.uid}">删除</button></td></tr>`).join('')}</tbody></table></section>`;
}

function renderGroups(){
  const e=state.event;
  const visibleGroups=state.groups.filter(group=>groupSession==='全部'||group.session===groupSession);
  const tailGroups=state.groups.filter(group=>group.members.length<e.group_size);
  app.innerHTML=`${context()}<section class="b-panel"><div class="b-panel-title"><h2>盲排分组结果 <small>每日确认截止后执行 · ${e.group_size} 人一组 · 4 位房号人工写入</small></h2></div>
    <div class="b-rule-summary">共 ${state.users.length} 名选手，分成 ${state.groups.length} 组。${tailGroups.length?`其中 ${tailGroups.map(g=>`第 ${g.id} 组为尾组 ${g.members.length} 人`).join('；')}，不足 ${e.group_size} 人照常开赛，不自动补人。`:'当前所有分组均已满员。'}</div>
    <div class="b-stage-tabs">${e.days.map(day=>`<button class="${day===e.current_date?'on':''}" data-action="group-date" data-date="${day}">${day}</button>`).join('')}</div>
    <div class="b-filters"><button class="b-button" data-action="shuffle-groups">立即执行盲排</button><button class="b-button o" data-action="manual-group">手工调整分组</button><button class="b-button o" data-action="export-groups">导出分组表</button><select class="b-select" data-action="group-session" style="margin-left:auto"><option value="全部">场次：全部</option>${e.sessions.map(session=>`<option value="${session}" ${groupSession===session?'selected':''}>场次：${session} 场</option>`).join('')}</select></div>
    <table class="b-table"><thead><tr><th>组号</th><th>时间</th><th>官方房间号</th><th>成员</th><th>通知状态</th><th>操作</th></tr></thead><tbody>${visibleGroups.length?visibleGroups.map(group=>`<tr><td>第 ${group.id} 组${group.members.length<e.group_size?`（尾组 ${group.members.length} 人）`:''}</td><td>${group.date} ${group.session}</td><td><b style="color:var(--blue);font-size:16px">${group.room}</b></td><td>${group.members.map(uid=>esc(state.users.find(u=>u.uid===uid).nickname)).join(' / ')}</td><td>${group.notified?'<span class="c-tag confirmed">已下发</span>':'<span class="c-tag pending">待下发</span>'}</td><td><button data-action="edit-room" data-group="${group.id}">编辑房间号</button></td></tr>`).join(''):'<tr><td colspan="6" class="b-empty">该场次暂无分组，可切换其他场次查看</td></tr>'}</tbody></table><p class="b-note">房间号被占用时可随时修改，修改后系统重新下发房间号通知给该组用户。</p></section>`;
}

function renderReview(){
  if(!state.matches.some(m=>m.id===selectedMatch))selectedMatch=(state.matches.find(m=>m.status==='pending')||state.matches[0]||{}).id;
  const match=state.matches.find(m=>m.id===selectedMatch);
  if(!match){app.innerHTML=`${context()}<section class="b-panel b-empty">当前赛段暂无赛果</section>`;return}
  const award=match.results.reduce((sum,result)=>sum+result.points,0);
  app.innerHTML=`${context()}<div class="b-review-grid"><section class="b-panel"><div class="b-panel-title"><h2>待审核场次 <small>AI 识图 + 人工复核</small></h2></div><div class="b-review-list">${state.matches.map(m=>`<button class="b-review-item ${m.id===selectedMatch?'on':''}" data-action="select-match" data-match="${m.id}"><b>第 ${m.group_id} 组 · 第 ${m.round} 局</b><span>${m.date} ${m.session}</span><div style="margin-top:7px">${statusTag(m.status)}</div></button>`).join('')}</div></section>
    <section class="b-panel"><div class="b-panel-title"><h2>战绩截图 <small>第 ${match.group_id} 组 · ${match.date} ${match.session} · 第 ${match.round} 局</small></h2><div class="b-actions"><button class="b-button o" data-action="next-match">下一个</button><button class="b-button green" data-action="confirm-review" data-match="${match.id}" ${match.status!=='pending'?'disabled':''}>确认结果</button></div></div><div class="b-screenshot" data-action="preview-screenshot" data-match="${match.id}" style="cursor:zoom-in" title="点击放大截图">${match.image?`<img src="${match.image}" alt="战绩截图">`:match.status==='not_uploaded'?'［ 游戏结算截图大图 · 等待上传 ］':'［ 本地模拟截图占位 · 支持上传后查看 ］'}</div>
      <div class="b-panel-title" style="margin-top:16px"><h2>AI 识图结果 <small>人工确认后积分生效</small></h2></div><table class="b-table"><thead><tr><th>名次</th><th>昵称</th><th>${match.status==='confirmed'?'已加分':'预记积分'}</th><th>匹配</th><th>操作</th></tr></thead><tbody>${match.results.map(r=>`<tr><td class="rank-cell">${r.rank}</td><td>${esc(r.nickname)}</td><td><b style="color:${match.status==='confirmed'?'var(--green)':'#536078'}">${match.status==='confirmed'?`+${r.points} 已加分`:`预记 ${r.points}`}</b></td><td>${r.match_state==='matched'?'已匹配':'未识别'}</td><td><button data-action="edit-result" data-match="${match.id}" data-uid="${r.uid}">修改</button></td></tr>`).join('')}</tbody></table><button class="b-button o c-block-btn" data-action="export-review">导出赛果 Excel</button></section>
    <section class="b-panel"><div class="b-panel-title"><h2>审核与修订记录</h2></div><div class="b-rule-summary">状态：${match.status==='confirmed'?'已审核':match.status==='pending'?'AI 完成，待人工确认':'等待上传'}<br>上传：${match.uploaded_at||'—'}<br>审核：${match.confirmed_at||'—'}${match.status==='confirmed'?`<br><b style="color:var(--green);font-size:14px">本局全组已加分：+${award} 分</b>`:'<br>审核完成后展示本局实际加分'}<br><br>仅可修正积分，名次保持不变，全部修改保留日志。</div><div class="b-revisions" style="margin-top:12px">${match.revisions.length?match.revisions.map(r=>`<div class="b-revision"><b>${esc(r.time)} · ${esc(r.operator)}</b>${esc(r.text)}</div>`).join(''):'<div class="b-empty">暂无修订记录</div>'}</div></section></div>`;
}

function renderAdvance(){
  const e=state.event;
  const eligible=state.users.filter(u=>state.stats[u.uid].eligible);
  const expected=state.users.filter(u=>state.stats[u.uid].expected_advance);
  const visibleUids=state.ranking.filter(uid=>{const u=state.users.find(x=>x.uid===uid),s=state.stats[uid];const queryMatch=!advanceQuery||u.nickname.includes(advanceQuery)||uid.includes(advanceQuery);const statusMatch=advanceStatus==='全部'||(advanceStatus==='预计晋级'&&s.expected_advance)||(advanceStatus==='未晋级'&&!s.expected_advance)||(advanceStatus==='正式晋级'&&u.advance_official);return queryMatch&&statusMatch});
  app.innerHTML=`${context()}<div class="b-stats"><div class="b-stat"><b>${state.users.length}</b><span>赛段报名用户</span></div><div class="b-stat"><b>${state.users.filter(u=>state.stats[u.uid].valid_days>=e.min_valid_days).length}</b><span>满足最低有效天数</span></div><div class="b-stat"><b>${eligible.length}</b><span>达到最低积分线</span></div><div class="b-stat"><b style="color:var(--blue)">${expected.length}</b><span>预计晋级</span></div><div class="b-stat"><b style="color:var(--orange)">${state.tie_pending.length}</b><span>边界同分待处理</span></div><div class="b-stat"><b>${state.users.filter(u=>state.stats[u.uid].supplemental).length}</b><span>运营补录</span></div></div>
    <div class="b-advance-grid"><section class="b-panel"><div class="b-panel-title"><h2>${esc(e.name)} · ${esc(e.stage)}预计晋级名单 <small>运营确认发布后才正式生效</small></h2></div><div class="b-rule-summary">当前判定：至少 ${e.min_valid_days} 个有效日；取最好 ${e.best_days} 天累计；最低 ${e.min_score} 分，按总积分排名取前 ${e.advance_quota} 人。</div>
      ${state.tie_pending.length?`<div class="b-rule-summary" style="background:#fff6e5;border-color:#f0d79b;color:#946515;margin-top:12px">晋级边界有 ${state.tie_pending.length} 人同分，请先处理再发布。<button class="b-button o" data-action="handle-tie" style="margin-left:12px">处理同分</button></div>`:''}
      <div class="b-filters" style="margin-top:14px"><form id="b-advance-search" class="b-actions"><input class="b-input" name="query" value="${esc(advanceQuery)}" placeholder="UID / 昵称"><select class="b-select" name="status"><option ${advanceStatus==='全部'?'selected':''}>全部</option><option ${advanceStatus==='预计晋级'?'selected':''}>预计晋级</option><option ${advanceStatus==='未晋级'?'selected':''}>未晋级</option><option ${advanceStatus==='正式晋级'?'selected':''}>正式晋级</option></select><button class="b-button" type="submit">查询</button></form><button class="b-button o" data-action="refresh">刷新</button><button class="b-button o" data-action="export-advance">导出名单</button><button class="b-button o" data-action="supplement">手动补录</button><button class="b-button" data-action="publish-advance">确认并发布</button></div>
      <table class="b-table"><thead><tr><th>排名</th><th>用户 ID</th><th>昵称</th><th>有效天数</th><th>计入成绩</th><th>总积分</th><th>系统判定</th><th>名单状态</th><th>操作</th></tr></thead><tbody>${visibleUids.length?visibleUids.map(uid=>{const u=state.users.find(x=>x.uid===uid),s=state.stats[uid];return `<tr><td class="rank-cell">${s.rank}</td><td>${uid}</td><td>${esc(u.nickname)}</td><td>${s.valid_days}/${e.min_valid_days}</td><td>最好 ${e.best_days} 天</td><td>${s.total_score}</td><td>${s.supplemental?'运营补录':s.expected_advance?'达标':s.valid_days<e.min_valid_days?'有效天数不足':'低于积分线'}</td><td>${u.advance_official?'<span class="c-tag advance">正式晋级</span>':s.expected_advance?'<span class="c-tag pending">预计晋级</span>':'<span class="c-tag invalid">不自动晋级</span>'}</td><td><button data-action="player-detail" data-uid="${uid}">成绩明细</button></td></tr>`}).join(''):'<tr><td colspan="9" class="b-empty">没有符合筛选条件的选手</td></tr>'}</tbody></table><p class="b-note">预计状态不会发送晋级通知；手动补录标记原因并保留操作记录。</p></section>
    <aside class="b-panel b-side-ranking b-rank-publish"><div class="b-panel-title"><h2>侧面榜单页 <small>直接连接 C 端榜单</small></h2></div><p class="b-note" style="margin-top:0">只有确认发布后才会在 C 端展示。榜单与晋级名单分别发布。</p><button class="b-button c-block-btn" data-action="publish-ranking">${e.ranking_published?'重新确认并发布榜单':'确认并发布榜单'}</button><div style="margin-top:12px">${state.ranking.map((uid,index)=>{const u=state.users.find(x=>x.uid===uid),s=state.stats[uid];return `<div class="b-rank-row"><span class="no">${index+1}</span><span class="name">${esc(u.nickname)}</span><span class="score">${s.total_score} 分</span></div>`}).join('')}</div></aside></div>`;
}

function renderMessages(){
  const tabs=[['mass','群发消息'],['config','消息配置'],['receipt','回执与未读']];
  const batches=state.message_batches;
  const total=batches.reduce((sum,b)=>sum+b.total,0),delivered=batches.reduce((sum,b)=>sum+b.delivered,0),read=batches.reduce((sum,b)=>sum+b.read_count,0),unread=total-read;
  let content='';
  if(messageTab==='mass')content=`<section class="b-panel"><div class="b-panel-title"><h2>定制群发 <small>全部通知仅在点点 App 端内执行</small></h2></div><form id="b-message-form" class="b-modal-form"><label>消息标题<input class="b-input" name="title" value="赛事通知" required></label><label>接收人分类<select class="b-select" name="target"><option value="current">当前演示用户 · ${esc(state.current_user.nickname)}</option><option value="all">全部报名用户（${state.users.length} 人）</option><option value="advance_expected">预计晋级用户（${state.users.filter(u=>state.stats[u.uid].expected_advance).length} 人）</option><option value="advance_official">正式晋级用户（${state.users.filter(u=>u.advance_official).length} 人）</option><option value="unread">历史消息未读用户（${new Set(state.messages.filter(m=>!m.read).map(m=>m.uid)).size} 人）</option><option value="group_current">当前小组（${state.group.members.length} 人）</option></select></label><label>消息内容<textarea class="b-input" name="content" rows="5" required>请于 ${state.event.current_date} ${state.event.sessions[0]} 进入万象棋房间 ${state.group.room}，完成当天全部比赛。</textarea></label><p class="b-note">每次发送形成一个独立消息批次，后续按批次统计各自的未读人群。</p><button class="b-button" type="submit">预览消息</button></form></section>`;
  if(messageTab==='config')content=`<section class="b-panel"><div class="b-panel-title"><h2>通知节点配置 <small>晋级公告仅由正式名单发布触发</small></h2></div>${Object.entries(state.event.message_settings).map(([key,cfg])=>`<div class="b-log"><span style="width:160px"><b>${esc(cfg.title)}</b><br><span class="c-muted">${esc(cfg.trigger)}</span></span><span style="flex:1">${esc(cfg.content)}<br><span class="c-muted">站内信 + App 推送</span></span><button class="b-button o" data-action="edit-message-config" data-key="${key}">编辑</button><button class="b-button ${cfg.enabled?'green':'gray'}" data-action="toggle-message-config" data-key="${key}">${cfg.enabled?'已开启':'已关闭'}</button></div>`).join('')}</section>`;
  if(messageTab==='receipt'){
    const visible=batches.filter(b=>!receiptUnreadOnly||b.unread_uids.length);
    content=`<div class="b-stats" style="grid-template-columns:repeat(4,1fr)"><div class="b-stat"><b>${total}</b><span>已发通知（条）</span></div><div class="b-stat"><b style="color:var(--green)">${total?Math.round(delivered/total*1000)/10:0}%</b><span>送达率</span></div><div class="b-stat"><b style="color:var(--blue)">${total?Math.round(read/total*1000)/10:0}%</b><span>已读率</span></div><div class="b-stat"><b style="color:var(--red)">${unread}</b><span>未读人数（待跟进）</span></div></div><section class="b-panel"><div class="b-panel-title"><h2>消息批次与回执 <small>每一批次独立统计未读人群</small></h2><div class="b-actions"><button class="b-button o" data-action="toggle-unread">${receiptUnreadOnly?'查看全部':'仅看未读批次'}</button><button class="b-button o" data-action="export-unread">导出全部未读</button></div></div><table class="b-table"><thead><tr><th>时间</th><th>通知类型</th><th>接收人数</th><th>送达</th><th>已读</th><th>未读</th><th>操作</th></tr></thead><tbody>${visible.length?visible.map(b=>`<tr><td>${b.time}</td><td>${esc(b.title)}</td><td>${b.total}</td><td>${b.delivered}</td><td style="color:var(--green)">${b.read_count}</td><td style="color:var(--red)">${b.unread_uids.length}</td><td><button data-action="view-batch-unread" data-id="${b.id}">查看未读</button><button data-action="resend-batch" data-id="${b.id}">重发未读</button><button data-action="export-batch-unread" data-id="${b.id}">导出</button></td></tr>`).join(''):'<tr><td colspan="7" class="b-empty">当前没有未读消息批次</td></tr>'}</tbody></table></section>`;
  }
  app.innerHTML=`${context()}<div class="b-stage-tabs">${tabs.map(([key,label])=>`<button class="${messageTab===key?'on':''}" data-action="message-tab" data-tab="${key}">${label}</button>`).join('')}</div>${content}`;
}

function showPlayer(uid){const u=state.users.find(x=>x.uid===uid),s=state.stats[uid],stageValues=u.stage_signup_values?.[state.current_stage_id]||{};openModal(`<h2>选手报名资料 · UID ${u.uid}</h2><p class="modal-desc">${esc(u.nickname)} · 仅展示报名收集项与归属信息</p><table class="b-table"><tbody><tr><th>联系方式（二选一）</th><td>${esc(stageValues.contact_type||u.contact_type||'微信')}：${esc(stageValues.contact_value||u.contact_value||u.wechat)}</td></tr><tr><th>手机号</th><td>${esc(u.phone)}</td></tr><tr><th>游戏昵称</th><td>${esc(u.game_nick)}</td></tr><tr><th>游戏 ID</th><td>${esc(u.game_id)}</td></tr><tr><th>账号渠道</th><td>${esc(u.channel)}</td></tr><tr><th>领队归属</th><td><b>${esc(leaderText(u))}</b></td></tr><tr><th>次日确认</th><td>${state.event.next_date} ${esc(u.next_session)}</td></tr>${Object.entries(u.custom_values||{}).map(([key,value])=>`<tr><th>自定义收集项</th><td>${esc(value)}</td></tr>`).join('')}</tbody></table>`)}
function showScores(uid){const u=state.users.find(x=>x.uid===uid),s=state.stats[uid],group=state.groups.find(g=>g.members.includes(uid)),matches=group?state.matches.filter(m=>m.group_id===group.id).sort((a,b)=>a.round-b.round):[];openModal(`<h2>成绩明细 · ${esc(u.nickname)}</h2><p class="modal-desc">UID ${uid} · 领队归属：<b>${esc(leaderText(u))}</b> · ${group?`第 ${group.id} 组`:'暂未分组'}</p><div class="b-rule-summary">有效参赛 ${s.valid_days}/${state.event.min_valid_days} 天 · 计入 ${s.counted_days} 天 · 总积分 <b>${s.total_score}</b> · 今日 ${s.played}/${state.event.daily_matches} 局</div><h3>逐局成绩</h3>${matches.length?matches.map(m=>{const r=m.results.find(x=>x.uid===uid);return `<div class="b-log"><time>第 ${m.round} 局</time><span>第 ${r?r.rank:'—'} 名 · ${r?r.points:0} 分<br><span class="c-muted">${m.date} ${m.session}</span></span>${statusTag(m.status)}</div>`}).join(''):'<div class="b-empty">暂无逐局成绩</div>'}<h3>历史有效日</h3><p class="c-muted">${(u.history_by_stage?.[state.current_stage_id]||[]).join(' 分 / ')||'暂无'}${(u.history_by_stage?.[state.current_stage_id]||[]).length?' 分':''}</p>`)}
function showEditResult(matchId,uid){const match=state.matches.find(m=>m.id===matchId),result=match.results.find(r=>r.uid===uid);openModal(`<h2>修改赛果积分</h2><p class="modal-desc">第 ${match.group_id} 组第 ${match.round} 局 · 名次保持第 ${result.rank} 名不变，仅允许修正积分</p><form id="b-result-form" class="b-modal-form"><input type="hidden" name="match_id" value="${matchId}"><input type="hidden" name="uid" value="${uid}"><label>昵称<input class="b-input" value="${esc(result.nickname)}" readonly></label><label>名次<input class="b-input" value="第 ${result.rank} 名（不可修改）" readonly></label><label>积分<input class="b-input" type="number" min="0" name="points" value="${result.points}" required></label><button class="b-button" type="submit">确认修改积分</button></form>`)}

document.querySelectorAll('[data-page]').forEach(btn=>btn.addEventListener('click',()=>goPage(btn.dataset.page)));
document.addEventListener('click',async event=>{
  const pageBtn=event.target.closest('#b-app [data-page]');if(pageBtn){goPage(pageBtn.dataset.page);return}
  const btn=event.target.closest('[data-action]');if(!btn)return;
  const action=btn.dataset.action;
  try{
    if(action==='close-modal')closeModal();
    if(action==='refresh')await refresh();
    if(action==='event-search'){eventUid=document.getElementById('b-event-uid').value.trim();eventStatus=document.getElementById('b-event-status').value;eventMonth=document.getElementById('b-event-month').value;eventQuery=document.getElementById('b-event-keyword').value.trim();renderEvents()}
    if(action==='event-clear'){eventUid='';eventStatus='全部';eventMonth='全部';eventQuery='';renderEvents()}
    if(action==='create-event')openModal(`<h2>新增赛事</h2><p class="modal-desc">大赛事保存后，再进入规则配置新增和管理小赛段。本地生成演示选手便于联调。</p><form id="b-event-form" class="b-modal-form"><label>赛事名称<input class="b-input" name="name" value="万象棋全民挑战杯" required></label><div class="b-form-grid"><div class="b-form-item"><label>游戏板块</label><select class="b-select" name="game">${['王者万象棋','王者荣耀','和平精英','三角洲行动','狼人杀'].map(game=>`<option ${game===selectedGame?'selected':''}>${game}</option>`).join('')}</select></div><div class="b-form-item"><label>比赛赛季</label><input class="b-input" name="season" value="S3" required></div></div><label>banner 展示开始时间<input class="b-input" type="datetime-local" name="banner_start" value="2025-12-20T00:00" required></label><label>banner 展示结束时间<input class="b-input" type="datetime-local" name="banner_end" value="2025-12-31T23:59" required></label><label>报名开始时间<input class="b-input" type="datetime-local" name="signup_start" value="2025-12-20T12:00" required></label><label>报名结束时间<input class="b-input" type="datetime-local" name="signup_end" value="2025-12-27T12:00" required></label><p class="b-note">点击输入框右侧日历图标可选择日期和时间，保存后显示在赛事列表。</p><button class="b-button" type="submit">保存并配置赛段规则</button></form>`);
    if(action==='board-select'){selectedGame=btn.dataset.game;const target=gameEvents()[0];if(target){state=await post('/api/event/select',{event_id:target.id});selectedMatch=null}activePage='events';render()}
    if(action==='event-page'){selectedGame=state.event_options.find(e=>e.id===Number(btn.dataset.id)).game;state=await post('/api/event/select',{event_id:btn.dataset.id});activePage=btn.dataset.target;selectedMatch=null;render()}
    if(action==='select-stage'){state=await post('/api/stage/select',{stage_id:btn.dataset.id});selectedMatch=null;render()}
    if(action==='create-stage')openModal(`<h2>新增赛段</h2><p class="modal-desc">复制当前赛段规则作为初始值，保存后可独立修改名称、日期、局数、积分与晋级名额。</p><form id="b-stage-form" class="b-modal-form"><label>赛段名称<input class="b-input" name="name" value="附加赛" required></label><label>开始日期<input class="b-input" type="date" name="start_date" value="${state.event.end_date}" required></label><label>结束日期<input class="b-input" type="date" name="end_date" value="${state.event.end_date}" required></label><button class="b-button" type="submit">新增并进入该赛段</button></form>`);
    if(action==='delete-stage'){if(!confirm(`确定删除“${state.event.stage}”及其本地演示分组赛果吗？`))return;state=await post('/api/stage/delete');selectedMatch=null;render();toast('赛段已删除')}
    if(action==='day-override')openModal(`<h2>单日局数调整 · ${btn.dataset.date}</h2><p class="modal-desc">仅影响当前赛段的该日期，其他日期继续沿用赛段默认值。</p><form id="b-day-form" class="b-modal-form"><input type="hidden" name="date" value="${btn.dataset.date}"><label>当日要求局数<input class="b-input" type="number" min="1" max="6" name="matches" value="${state.event.daily_overrides[btn.dataset.date]||state.event.default_matches}"></label><button class="b-button" type="submit">确认保存</button></form>`);
    if(action==='player-detail')showPlayer(btn.dataset.uid);
    if(action==='score-detail')showScores(btn.dataset.uid);
    if(action==='add-player')openModal(`<h2>手工补录选手</h2><p class="modal-desc">补录后进入当前大赛事选手列表。</p><form id="b-add-player-form" class="b-modal-form"><label>用户 UID<input class="b-input" name="uid" required></label><label>昵称<input class="b-input" name="nickname" value="补录选手"></label><button class="b-button" type="submit">确认补录</button></form>`);
    if(action==='player-template')downloadCsv('比赛玩家模板.csv',[['UID','昵称','微信号','手机号','游戏昵称','游戏ID','账号渠道']]);
    if(action==='assign-leaders'){state=await post('/api/leaders/assign');render();toast('已按领队 UID 和容量完成匹配并自动建群')}
    if(action==='assign-player-leader'){const u=state.users.find(x=>x.uid===btn.dataset.uid);openModal(`<h2>调整选手领队</h2><p class="modal-desc">${esc(u.nickname)} · UID ${u.uid} · 当前 ${esc(leaderText(u))}</p><form id="b-player-leader-form" class="b-modal-form"><input type="hidden" name="uid" value="${u.uid}"><label>选择领队<select class="b-select" name="leader_uid">${state.leader_options.filter(l=>l.enabled).map(l=>`<option value="${l.uid}" ${l.uid===u.leader_uid?'selected':''}>${esc(l.name)}（UID ${l.uid}）· 剩余 ${Math.max(0,l.capacity-l.assigned_count)} 人</option>`).join('')}</select></label><button class="b-button" type="submit">确认调整领队</button></form>`)}
    if(action==='add-leader')openModal(`<h2>新增领队</h2><p class="modal-desc">领队 UID 是分配关系的唯一标识，保存后立即可用于选手分配。</p><form id="b-leader-add-form" class="b-modal-form"><label>领队 UID<input class="b-input" name="uid" inputmode="numeric" pattern="[0-9]+" placeholder="例如：88001004" required></label><label>领队昵称<input class="b-input" name="name" value="领队-新辰" required></label><label>可管理用户上限<input class="b-input" type="number" min="1" max="50" name="capacity" value="8" required></label><button class="b-button" type="submit">保存并启用</button></form>`);
    if(action==='edit-leader'){const l=state.leader_options.find(x=>x.uid===btn.dataset.uid);openModal(`<h2>编辑领队容量</h2><p class="modal-desc">${esc(l.name)} · UID ${l.uid} · 已分配 ${l.assigned_count} 人</p><form id="b-leader-edit-form" class="b-modal-form"><input type="hidden" name="uid" value="${l.uid}"><input type="hidden" name="enabled" value="${l.enabled}"><label>可管理用户上限<input class="b-input" type="number" min="1" max="50" name="capacity" value="${l.capacity}" required></label><button class="b-button" type="submit">保存容量</button></form>`)}
    if(action==='toggle-leader'){const l=state.leader_options.find(x=>x.uid===btn.dataset.uid);state=await post('/api/leaders/update',{uid:l.uid,capacity:l.capacity,enabled:!l.enabled});render();toast(l.enabled?'领队已停用':'领队已启用')}
    if(action==='delete-leader'){if(!confirm('确认删除该领队吗？名下有选手时无法删除。'))return;state=await post('/api/leaders/delete',{uid:btn.dataset.uid});render();toast('领队已删除')}
    if(action==='add-session'){const container=document.getElementById('b-session-inputs');if(container.children.length>=3){toast('每日最多 3 个场次');return}container.insertAdjacentHTML('beforeend','<div class="b-session-input" style="display:flex;gap:6px;margin-bottom:5px"><input class="b-input" type="time" step="3600" name="session" value="20:00" required><button class="b-button o" type="button" data-action="remove-session">删除</button></div>')}
    if(action==='remove-session'){const container=document.getElementById('b-session-inputs');if(container.children.length<=1){toast('至少保留一个场次');return}btn.closest('.b-session-input').remove()}
    if(action==='add-field')openModal(`<h2>添加自定义收集项</h2><p class="modal-desc">可创建文本输入或自定义选项，保存后对应 C 端表单立即生效。</p><form id="b-field-form" class="b-modal-form"><input type="hidden" name="scope" value="${btn.dataset.scope}"><label>收集项名称<input class="b-input" name="label" placeholder="例如：所属战队 / 常用位置 / 联系方式" required></label><label>收集形式<select class="b-select" name="type"><option value="text">文本输入</option><option value="select">自定义选项</option></select></label><label>自定义选项（逗号分隔，文本输入可留空）<input class="b-input" name="options" placeholder="例如：上单,打野,中路,辅助"></label><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="required" checked>该收集项为必填</label><button class="b-button" type="submit">保存收集项</button></form>`);
    if(action==='delete-field'){state=await post('/api/fields/delete',{scope:btn.dataset.scope,field_id:btn.dataset.id});render();toast('自定义收集项已删除')}
    if(action==='group-date'){state=await post('/api/stage/current-date',{date:btn.dataset.date});selectedMatch=null;render()}
    if(action==='manual-group')openModal(`<h2>手工调整分组</h2><p class="modal-desc">选择选手和目标分组，移动后两端赛程及对应局次成员同步更新。</p><form id="b-move-group-form" class="b-modal-form"><label>选择选手<select class="b-select" name="uid">${state.users.map(u=>`<option value="${u.uid}">${esc(u.nickname)} · ${u.uid} · 当前第 ${(state.groups.find(g=>g.members.includes(u.uid))||{}).id||'—'} 组</option>`).join('')}</select></label><label>目标分组<select class="b-select" name="group_id">${state.groups.map(g=>`<option value="${g.id}">第 ${g.id} 组（${g.members.length} 人）</option>`).join('')}</select></label><button class="b-button" type="submit">确认调整</button></form>`);
    if(action==='shuffle-groups'){if(!confirm('重新盲排会重置当前赛段分组和当日局次，是否继续？'))return;state=await post('/api/groups/shuffle');render();toast('当前赛段已重新盲排')}
    if(action==='export-groups')downloadCsv('分组表.csv',[['组号','日期','场次','房间号','成员'],...state.groups.map(g=>[g.id,g.date,g.session,g.room,g.members.map(uid=>state.users.find(u=>u.uid===uid).nickname).join(' / ')])]);
    if(action==='edit-room'){const group=state.groups.find(g=>g.id===Number(btn.dataset.group));openModal(`<h2>编辑房间号 · 第 ${group.id} 组</h2><p class="modal-desc">万象棋官方 4 位房间号，保存后重新通知组员。</p><form id="b-room-form" class="b-modal-form"><input type="hidden" name="group_id" value="${group.id}"><label>官方房间号<input class="b-input" name="room" value="${group.room==='待录入'?'':group.room}" maxlength="4" pattern="[0-9]{4}" required></label><button class="b-button" type="submit">保存并重发通知</button></form>`)}
    if(action==='select-match'){selectedMatch=btn.dataset.match;renderReview()}
    if(action==='next-match'){const index=state.matches.findIndex(m=>m.id===selectedMatch);selectedMatch=state.matches[(index+1)%state.matches.length].id;renderReview()}
    if(action==='edit-result')showEditResult(btn.dataset.match,btn.dataset.uid);
    if(action==='confirm-review'){if(!confirm('确认本组本局赛果吗？确认后积分生效。'))return;state=await post('/api/review/confirm',{match_id:btn.dataset.match});render();toast('赛果已确认，榜单草稿已更新')}
    if(action==='export-review'){const match=state.matches.find(m=>m.id===selectedMatch);downloadCsv('赛果.csv',[['日期','场次','组号','局次','UID','昵称','名次','积分'],...match.results.map(r=>[match.date,match.session,match.group_id,match.round,r.uid,r.nickname,r.rank,r.points])])}
    if(action==='preview-screenshot'){const match=state.matches.find(m=>m.id===btn.dataset.match);openModal(`<h2>战绩截图 · 第 ${match.group_id} 组第 ${match.round} 局</h2><p class="modal-desc">${match.date} ${match.session} · 点击外部区域关闭</p>${match.image?`<img src="${match.image}" style="width:100%;border-radius:10px">`:'<div class="b-empty">当前为模拟截图占位，暂无实际上传图片</div>'}`)}
    if(action==='supplement')openModal(`<h2>运营手动补录</h2><p class="modal-desc">补录后进入预计晋级名单，仍须统一发布才正式生效。</p><form id="b-supplement-form" class="b-modal-form"><label>选择用户<select class="b-select" name="uid">${state.users.filter(u=>!state.stats[u.uid].expected_advance).map(u=>`<option value="${u.uid}">${esc(u.nickname)} · ${u.uid} · ${state.stats[u.uid].total_score} 分</option>`).join('')}</select></label><label>补录原因<input class="b-input" name="reason" value="名额未满，结合参赛情况补录" required></label><button class="b-button" type="submit">加入预计名单</button></form>`);
    if(action==='handle-tie')openModal(`<h2>处理晋级边界同分</h2><p class="modal-desc">边界共有 ${state.tie_pending.length} 人同分，系统不会擅自决定录取人选。请选择最终录取者并填写依据。</p><form id="b-tie-form" class="b-modal-form"><input type="hidden" name="uids" value="${state.tie_pending.join(',')}"><label>最终录取<select class="b-select" name="selected_uid">${state.tie_pending.map(uid=>{const u=state.users.find(x=>x.uid===uid);return `<option value="${uid}">${esc(u.nickname)} · ${uid} · ${state.stats[uid].total_score} 分</option>`}).join('')}</select></label><label>处理原因<input class="b-input" name="reason" value="根据当届赛事同分处理规则，运营确认录取" required></label><button class="b-button" type="submit">保存处理结果</button></form>`);
    if(action==='publish-advance'){if(state.tie_pending.length){toast('请先处理晋级边界同分人员');return}if(!confirm('确认发布当前赛段正式晋级名单吗？'))return;state=await post('/api/advance/publish');render();toast('正式晋级名单已发布')}
    if(action==='publish-ranking'){if(!confirm('确认将当前榜单发布到 C 端吗？'))return;state=await post('/api/ranking/publish');render();toast('C 端榜单已发布')}
    if(action==='export-advance')downloadCsv('晋级名单.csv',[['排名','UID','昵称','有效天数','总积分','是否预计晋级'],...state.ranking.map(uid=>{const u=state.users.find(x=>x.uid===uid),s=state.stats[uid];return [s.rank,uid,u.nickname,s.valid_days,s.total_score,s.expected_advance?'是':'否']})]);
    if(action==='message-tab'){messageTab=btn.dataset.tab;renderMessages()}
    if(action==='toggle-message-config'){const key=btn.dataset.key;state=await post('/api/message/config',{key,enabled:!state.event.message_settings[key].enabled});render();toast('自动消息开关已更新')}
    if(action==='edit-message-config'){const key=btn.dataset.key,cfg=state.event.message_settings[key];openModal(`<h2>编辑自动消息</h2><p class="modal-desc">${esc(cfg.trigger)} · 保存后保留在当前赛事。</p><form id="b-message-config-form" class="b-modal-form"><input type="hidden" name="key" value="${key}"><input type="hidden" name="enabled" value="${cfg.enabled}"><label>消息标题<input class="b-input" name="title" value="${esc(cfg.title)}" required></label><label>消息内容<textarea class="b-input" name="content" rows="5" required>${esc(cfg.content)}</textarea></label><p class="b-note">可用变量：{赛事名} {阶段} {场次} {时间} {房间号} {当日积分}</p><button class="b-button" type="submit">保存消息配置</button></form>`)}
    if(action==='confirm-mass'){if(!pendingMessage)return;state=await post('/api/message',pendingMessage);pendingMessage=null;closeModal();messageTab='receipt';render();toast('点点端内消息已发送')}
    if(action==='toggle-unread'){receiptUnreadOnly=!receiptUnreadOnly;renderMessages()}
    if(action==='export-unread')downloadCsv('未读消息名单.csv',[['UID','昵称','标题','内容','时间'],...state.messages.filter(m=>!m.read).map(m=>{const u=state.users.find(x=>x.uid===m.uid);return [m.uid,u?u.nickname:'',m.title,m.content,m.time]})]);
    if(action==='resend-message'){state=await post('/api/message/resend',{message_id:btn.dataset.id});render();toast('消息已重发，回执已更新')}
    if(action==='view-batch-unread'){const batch=state.message_batches.find(b=>b.id===btn.dataset.id);openModal(`<h2>未读名单 · ${esc(batch.title)}</h2><p class="modal-desc">本批次共 ${batch.total} 人，未读 ${batch.unread_uids.length} 人。未读人群与其他批次独立。</p><table class="b-table"><thead><tr><th>UID</th><th>昵称</th><th>领队归属</th><th>跟进状态</th></tr></thead><tbody>${batch.unread_uids.map(uid=>{const u=state.users.find(x=>x.uid===uid);return `<tr><td>${uid}</td><td>${esc(u.nickname)}</td><td>${esc(leaderText(u))}</td><td><span class="c-tag pending">待点点私聊</span></td></tr>`}).join('')}</tbody></table>`)}
    if(action==='resend-batch'){state=await post('/api/message/resend-batch',{batch_id:btn.dataset.id});render();toast('已向该批次未读用户重发')}
    if(action==='export-batch-unread'){const batch=state.message_batches.find(b=>b.id===btn.dataset.id);downloadCsv(`未读名单_${batch.title}.csv`,[['UID','昵称','领队UID'],...batch.unread_uids.map(uid=>{const u=state.users.find(x=>x.uid===uid);return [uid,u.nickname,u.leader_uid]})])}
  }catch(error){toast(error.message)}
});

document.addEventListener('change',async event=>{
  const el=event.target;
  try{
    if(el.dataset.action==='context-event'){state=await post('/api/event/select',{event_id:el.value});selectedMatch=null;render()}
    if(el.dataset.action==='context-stage'){state=await post('/api/stage/select',{stage_id:el.value});selectedMatch=null;render()}
    if(el.dataset.action==='group-session'){groupSession=el.value;renderGroups()}
    if(el.id==='b-demo-date'){state=await post('/api/demo-date',{date:el.value});render();toast('业务日期已切换，C 端可访问页面已同步')}
  }catch(error){toast(error.message)}
});

document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target,data=new FormData(form);
  try{
    if(form.id==='b-event-form'){selectedGame=String(data.get('game'));state=await post('/api/event/create',{name:data.get('name'),season:data.get('season'),game:data.get('game'),banner_start:data.get('banner_start'),banner_end:data.get('banner_end'),signup_start:data.get('signup_start'),signup_end:data.get('signup_end')});closeModal();activePage='rules';render();toast('大赛事已创建，请继续配置赛段')}
    if(form.id==='b-stage-form'){state=await post('/api/stage/create',{name:data.get('name'),start_date:data.get('start_date'),end_date:data.get('end_date')});closeModal();selectedMatch=null;render();toast('新赛段已创建')}
    if(form.id==='b-day-form'){state=await post('/api/stage/day-override',{date:data.get('date'),matches:data.get('matches')});closeModal();render();toast('单日局数已保存')}
    if(form.id==='b-rules-form'){const payload={name:data.get('name'),start_date:data.get('start_date'),end_date:data.get('end_date'),sessions:data.getAll('session').join(' / '),daily_matches:data.get('daily_matches'),min_valid_days:data.get('min_valid_days'),best_days:data.get('best_days'),min_score:data.get('min_score'),advance_quota:data.get('advance_quota'),group_size:data.get('group_size'),points:[0,1,2,3,4,5].map(i=>Number(data.get(`point${i}`))),registration_fields:data.getAll('fields'),require_signup:data.get('require_signup')==='on',stage_registration_fields:data.getAll('stage_fields')};state=await post('/api/rules',payload);render();toast('当前赛段规则已保存并同步 C 端')}
    if(form.id==='b-field-form'){state=await post('/api/fields/add',{scope:data.get('scope'),label:data.get('label'),type:data.get('type'),options:data.get('options'),required:data.get('required')==='on'});closeModal();render();toast('自定义收集项已添加，C 端表单已同步')}
    if(form.id==='b-player-search'){playerQuery=String(data.get('query')||'').trim();renderPlayers()}
    if(form.id==='b-move-group-form'){state=await post('/api/groups/move',{uid:data.get('uid'),group_id:data.get('group_id')});closeModal();render();toast('选手分组已调整，C 端赛程已同步')}
    if(form.id==='b-add-player-form'){state=await post('/api/players/add',{uid:data.get('uid'),nickname:data.get('nickname')});closeModal();render();toast('选手已补录')}
    if(form.id==='b-leader-add-form'){state=await post('/api/leaders/add',{uid:data.get('uid'),name:data.get('name'),capacity:data.get('capacity')});closeModal();render();toast('领队已加入领队库并启用')}
    if(form.id==='b-leader-edit-form'){state=await post('/api/leaders/update',{uid:data.get('uid'),capacity:data.get('capacity'),enabled:String(data.get('enabled'))==='true'});closeModal();render();toast('领队容量已更新')}
    if(form.id==='b-player-leader-form'){state=await post('/api/players/leader',{uid:data.get('uid'),leader_uid:data.get('leader_uid')});closeModal();render();toast('选手领队归属已更新')}
    if(form.id==='b-room-form'){state=await post('/api/room',{group_id:data.get('group_id'),room:data.get('room')});closeModal();render();toast('房间号已保存并重新通知')}
    if(form.id==='b-result-form'){state=await post('/api/review/result',{match_id:data.get('match_id'),uid:data.get('uid'),points:data.get('points')});closeModal();render();toast('积分已修改，名次保持不变')}
    if(form.id==='b-supplement-form'){state=await post('/api/advance/supplement',{uid:data.get('uid'),reason:data.get('reason')});closeModal();render();toast('已加入预计晋级名单')}
    if(form.id==='b-advance-search'){advanceQuery=String(data.get('query')||'').trim();advanceStatus=String(data.get('status'));renderAdvance()}
    if(form.id==='b-tie-form'){state=await post('/api/advance/tie',{uids:String(data.get('uids')).split(','),selected_uid:data.get('selected_uid'),reason:data.get('reason')});closeModal();render();toast('同分处理已保存，预计名单已更新')}
    if(form.id==='b-message-form'){pendingMessage={title:String(data.get('title')),target:String(data.get('target')),content:String(data.get('content'))};const targetText=({all:`全部报名用户（${state.users.length} 人）`,advance_expected:'预计晋级用户',advance_official:'正式晋级用户',unread:'历史消息未读用户',group_current:`当前第 ${state.group.id} 组（${state.group.members.length} 人）`,current:`${state.current_user.nickname}（${state.current_uid}）`})[data.get('target')];openModal(`<h2>确认发送点点消息</h2><p class="modal-desc">接收人：${targetText}</p><div class="b-rule-summary"><b>${esc(pendingMessage.title)}</b><br>${esc(pendingMessage.content)}</div><button class="b-button c-block-btn" data-action="confirm-mass">确认发送</button>`)}
    if(form.id==='b-message-config-form'){state=await post('/api/message/config',{key:data.get('key'),enabled:String(data.get('enabled'))==='true',title:data.get('title'),content:data.get('content')});closeModal();render();toast('自动消息配置已保存')}
  }catch(error){toast(error.message)}
});

document.getElementById('b-reset').addEventListener('click',async()=>{if(!confirm('确定恢复全部赛事的初始演示数据吗？'))return;state=await post('/api/reset');selectedMatch=null;playerQuery='';eventQuery='';render();toast('已恢复初始演示数据')});
modal.addEventListener('click',event=>{if(event.target===modal)closeModal()});
refresh().catch(error=>toast(error.message));
